import numpy as np


class FeasibilityRuleMixedDE:
    """Feasibility-rule DE with current-to-pbest/1 mutation over a budget-annealed ranked top
    fraction, self-adaptive per-individual discrete mutation rates, Lehmer-mean F/CR adaptation,
    a cross-run evaluation cache (repeated mixed-integer points are free), a deduplicated elite
    archive, and an incumbent-centred local search with per-coordinate adaptive steps and joint
    random-sign continuous probes. Restarts mix elite perturbation, elite crossover and random points."""

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float)
        ub = np.asarray(func.bounds.ub, dtype=float)
        vtypes = [str(t) for t in func.variable_types]
        cidx = np.array([i for i in range(d) if vtypes[i] == "continuous"], dtype=int)
        didx = np.array([i for i in range(d) if vtypes[i] != "continuous"], dtype=int)
        ordm = np.array([vtypes[i] == "ordinal" for i in range(d)])
        nv = np.ones(d, dtype=int)
        for i in didx:
            nv[i] = int(func.n_values[i])
        cwidth = np.where(ub - lb > 0, ub - lb, 1.0)

        cache = {}
        elites = []          # list of (f, x), feasible, best first, deduplicated
        elite_keys = set()
        st = {"evals": 0, "best_f": np.inf, "best_x": None}
        ELITE_N = 10

        def repair(X):
            X = np.clip(X, lb, ub)
            if didx.size:
                X[:, didx] = np.clip(np.rint(X[:, didx]), 0, nv[didx] - 1)
            return X

        def random_pop(n):
            X = np.empty((n, d))
            if cidx.size:
                X[:, cidx] = rng.uniform(lb[cidx], ub[cidx], size=(n, len(cidx)))
            if didx.size:
                X[:, didx] = rng.integers(0, nv[didx], size=(n, len(didx)))
            return X

        def key(x):
            return tuple(np.round(x, 9))

        def register_feasible(f, x):
            nonlocal elites
            kk = key(x)
            if kk in elite_keys:
                return
            elite_keys.add(kk)
            elites.append((f, x.copy()))
            elites.sort(key=lambda t: t[0])
            for _, ex in elites[ELITE_N:]:
                elite_keys.discard(key(ex))
            elites = elites[:ELITE_N]

        def evaluate(X):
            F, V = [], []
            for k in range(len(X)):
                x = X[k]
                kk = key(x)
                if kk in cache:
                    f, v = cache[kk]
                else:
                    if st["evals"] >= self.budget:
                        break
                    f, g = func(x.copy())
                    f = float(f)
                    g = np.atleast_1d(np.asarray(g, dtype=float))
                    v = float(np.sum(np.maximum(np.nan_to_num(g, nan=1e6), 0.0)))
                    if not np.isfinite(f):
                        f = np.inf
                        v += 1.0
                    cache[kk] = (f, v)
                    st["evals"] += 1
                    if v == 0.0 and np.isfinite(f):
                        if f < st["best_f"]:
                            st["best_f"] = f
                            st["best_x"] = x.copy()
                        register_feasible(f, x)
                F.append(f)
                V.append(v)
            return np.array(F, dtype=float), np.array(V, dtype=float)

        def better(fa, va, fb, vb):
            if va == 0 and vb == 0:
                return fa < fb
            if va == 0 or vb == 0:
                return va == 0
            return va < vb

        def best_index(F, V):
            feas = np.where(V == 0)[0]
            if feas.size:
                return int(feas[np.argmin(F[feas])])
            return int(np.argmin(V))

        def mutate_discrete(base, rate):
            x = base.copy()
            for j in didx:
                if nv[j] > 1 and rng.random() < rate:
                    if ordm[j]:
                        s = 1 if rng.random() < 0.5 else -1
                        nj = x[j] + s
                        if nj < 0 or nj >= nv[j]:
                            nj = x[j] - s
                        x[j] = nj
                    else:
                        nj = rng.integers(nv[j] - 1)
                        x[j] = nj + (1 if nj >= x[j] else 0)
            return x

        def perturb(x, scale):
            y = x.copy()
            if cidx.size:
                y[cidx] = y[cidx] + rng.normal(0.0, scale, len(cidx)) * cwidth[cidx]
            if didx.size:
                rate = rng.uniform(1.0 / max(len(didx), 1), 0.35)
                y = mutate_discrete(y, rate)
            return y

        def local_search(x0, f0, rounds=6, cap=80):
            """Incumbent-centred search: full discrete neighbourhood, per-coordinate
            continuous steps and joint random-sign probes; cached points are free."""
            x, fx, vx = x0.copy(), f0, 0.0
            steps = 0.05 * cwidth[cidx] if cidx.size else np.zeros(0)
            fails = 0
            for _ in range(rounds):
                if st["evals"] >= self.budget:
                    break
                cand, tags = [], []
                for j in didx:
                    for val in range(nv[j]):
                        if val != x[j]:
                            c = x.copy()
                            c[j] = val
                            cand.append(c)
                            tags.append(-1)
                for k, j in enumerate(cidx):
                    for s in (-1.0, 1.0):
                        c = x.copy()
                        c[j] = c[j] + s * steps[k]
                        cand.append(c)
                        tags.append(k)
                if cidx.size:
                    # joint random-sign probes over all continuous coordinates
                    for _p in range(2):
                        signs = rng.choice([-1.0, 1.0], size=len(cidx))
                        c = x.copy()
                        c[cidx] = c[cidx] + signs * steps
                        cand.append(c)
                        tags.append(-2)
                if not cand:
                    break
                tags = np.array(tags)
                if len(cand) > cap:
                    sel = rng.choice(len(cand), cap, replace=False)
                    cand = [cand[q] for q in sel]
                    tags = tags[sel]
                C = repair(np.array(cand))
                CF, CV = evaluate(C)
                if len(CF) == 0:
                    break
                bi = best_index(CF, CV)
                if better(CF[bi], CV[bi], fx, vx):
                    x, fx, vx = C[bi].copy(), CF[bi], CV[bi]
                    t = tags[bi]
                    if t >= 0:
                        steps[t] = min(0.5 * cwidth[cidx[t]], steps[t] * 1.5)
                    elif t == -2:
                        steps = np.minimum(0.5 * cwidth[cidx], steps * 1.2)
                    fails = 0
                else:
                    steps = steps * 0.5
                    fails += 1
                    if (steps.size == 0 or np.max(steps) < 1e-3 * cwidth[cidx].min()) or fails >= 3:
                        if not didx.size or fails >= 3:
                            break
            return x, fx, vx

        NP = int(min(40, max(10, self.budget // 15)))
        stall_limit = 25
        P_TOP_HI, P_TOP_LO = 0.25, 0.08

        while st["evals"] < self.budget:
            r = rng.random()
            if st["best_x"] is None or r < 0.25:
                X = random_pop(NP)
            else:
                X = np.empty((NP, d))
                n_pert = int(0.5 * NP)
                n_cross = int(0.25 * NP)
                for i in range(NP):
                    if i < n_pert:
                        X[i] = perturb(elites[rng.integers(len(elites))][1],
                                       rng.choice([0.02, 0.1, 0.3]))
                    elif i < n_pert + n_cross and len(elites) >= 2:
                        a, b2 = rng.choice(len(elites), 2, replace=False)
                        mask = rng.random(d) < 0.5
                        child = np.where(mask, elites[a][1], elites[b2][1])
                        X[i] = perturb(child, 0.02)
                    else:
                        X[i] = random_pop(1)[0]
                X = repair(X)
            if st["best_x"] is not None:
                X[0] = st["best_x"]
            F, V = evaluate(X)
            if len(F) < NP:
                break
            P, PF, PV = X, F, V
            DR = np.full(NP, 0.2)           # self-adaptive discrete mutation rates
            mu_F, mu_CR = 0.6, 0.8
            stall = 0

            while st["evals"] < self.budget and stall < stall_limit:
                prev = st["best_f"]
                order = np.lexsort((PF, PV))  # feasibility first, then objective
                frac = min(1.0, st["evals"] / max(self.budget, 1))
                p_top = P_TOP_HI + (P_TOP_LO - P_TOP_HI) * frac
                n_top = max(1, int(p_top * NP))
                Fi = np.clip(rng.normal(mu_F, 0.1, NP), 0.1, 1.0)
                CRi = np.clip(rng.normal(mu_CR, 0.1, NP), 0.0, 1.0)
                T = np.empty_like(P)
                Rused = np.empty(NP)

                for i in range(NP):
                    others = np.delete(np.arange(NP), i)
                    r1, r2 = rng.choice(others, 2, replace=False)
                    pb = order[rng.integers(n_top)]
                    xi = P[i]
                    f_ = Fi[i]
                    mutant = xi.copy()
                    if cidx.size:
                        mutant[cidx] = (xi[cidx]
                                        + f_ * (P[pb][cidx] - xi[cidx])
                                        + f_ * (P[r1][cidx] - P[r2][cidx]))
                    if didx.size:
                        base = P[r1] if rng.random() < 0.5 else P[pb]
                        rate = float(np.clip(DR[i] * rng.uniform(0.5, 1.5), 1.0 / d, 0.6))
                        Rused[i] = rate
                        dm = mutate_discrete(base, rate)
                        mutant[didx] = dm[didx]
                    mask = rng.random(d) < CRi[i]
                    mask[rng.integers(d)] = True
                    T[i] = np.where(mask, mutant, xi)

                T = repair(T)
                TF, TV = evaluate(T)
                m = len(TF)

                succF, succCR, succR = [], [], []
                for k in range(m):
                    if better(TF[k], TV[k], PF[k], PV[k]):
                        P[k] = T[k]
                        PF[k] = TF[k]
                        PV[k] = TV[k]
                        succF.append(Fi[k])
                        succCR.append(CRi[k])
                        succR.append(Rused[k] if didx.size else 0.2)
                        DR[k] = 0.7 * DR[k] + 0.3 * Rused[k] if didx.size else DR[k]
                    elif didx.size:
                        DR[k] = max(1.0 / d, 0.95 * DR[k])
                if succF:
                    sf = np.asarray(succF)
                    mu_F = 0.9 * mu_F + 0.1 * (np.sum(sf ** 2) / max(np.sum(sf), 1e-12))
                    mu_CR = 0.9 * mu_CR + 0.1 * float(np.mean(succCR))

                cur = st["best_f"]
                improved = np.isfinite(cur) and (
                    not np.isfinite(prev) or prev - cur > 1e-9 * max(1.0, abs(prev)))
                if improved:
                    stall = 0
                    lx, lf, lv = local_search(st["best_x"], st["best_f"])
                    if lv == 0 and np.isfinite(lf) and st["evals"] < self.budget:
                        ordw = np.lexsort((PF, PV))
                        w = ordw[-1]
                        P[w] = lx
                        PF[w] = lf
                        PV[w] = 0.0
                        DR[w] = 0.2
                else:
                    stall += 1
                if m < NP:
                    break

            if st["best_x"] is not None and st["evals"] < self.budget:
                local_search(st["best_x"], st["best_f"], rounds=4)

        return st["best_f"], st["best_x"]
